// =======================================
// 💬 Flash Message Function (Reusable)
function showFlashMessage(type, message, duration = 8000) {
    const flashMessage = document.createElement("div");
    flashMessage.className = `flash-message flash-${type}`;
    flashMessage.innerHTML = `
        ${message}
        <div class="flash-progress"></div>
    `;

    document.querySelector(".flash-container").appendChild(flashMessage);

    setTimeout(() => {
        flashMessage.classList.add("is-visible");
        flashMessage.querySelector(".flash-progress").style.width = "100%";
    }, 100);

    setTimeout(() => {
        flashMessage.classList.remove("is-visible");
        flashMessage.querySelector(".flash-progress").style.width = "0";
        setTimeout(() => {
            flashMessage.remove();
        }, 500);
    }, duration);
}

(function () {
    const currentUrl = window.location.href;

const shouldRedirect = [
    /_ja_inbox$/, 
    /action=assignmentSubmit/          

].some(regex => regex.test(currentUrl));

    const redirectUrl = localStorage.getItem("redirectUrl");

    if (shouldRedirect && redirectUrl) {
        // You can attach a flash message to the redirect URL if needed
        const msg = getUrlParam("msg");
        const type = getUrlParam("type");

        const url = new URL(redirectUrl);
        if (msg && type) {
            url.searchParams.set("msg", msg);
            url.searchParams.set("type", type);
        }

        localStorage.removeItem("redirectUrl");
        window.location.href = url.toString(); // 🔁 Perform redirect with params
        return; // Stop further execution
    }

    function getUrlParam(name) {
        return new URLSearchParams(window.location.search).get(name);
    }
})();
