$(document).ready(function () {
  console.log("✅ Script loaded");

  // Prevent execution multiple times in the same session
  if (sessionStorage.getItem("notificationBadgeHandled")) {
    console.log("⚠️ Notification already handled this session.");
    return;
  }

  // Poll until badge appears in DOM
  const checkBadge = setInterval(function () {
    const badge = document.querySelector('.notification-badge');

    if (badge) {
      const value = parseInt(badge.textContent.trim());
      console.log("🔔 Badge found with value:", value);

      if (value > 0) {
        console.log("🚀 Triggering notification popup");
        dlPostActionDelete();
      } else {
        console.log("ℹ️ Badge exists but value is 0");
      }

      // Mark as handled (you can conditionally store this only if value > 0)
      sessionStorage.setItem("notificationBadgeHandled", "true");
      clearInterval(checkBadge);
    } else {
      console.log("⏳ Waiting for .notification-badge...");
    }
  }, 300);
});

