    let loginUrl = "/jw/web/login";
    const params = new URLSearchParams(window.location.search);
    if (params.toString()) {
      loginUrl += `?${params.toString()}`;
    }
    try {
      localStorage.setItem("loginUrl", loginUrl);
    } catch (error) {
      console.warn("localStorage is not available:", error);
    }
  }

  // Handle logout link click
  const logoutLink = document.querySelector('a[href="/jw/j_spring_security_logout"]');
  if (logoutLink) {
    logoutLink.addEventListener("click", function (e) {
      e.preventDefault();
      try {
        // Set logout flag
        localStorage.setItem("isLoggingOut", "true");
      } catch (error) {
        console.warn("localStorage is not available:", error);
      }
      // Trigger logout
      window.location.href = "/jw/j_spring_security_logout";
    });
  }

  // After logout, check redirect condition
  if (window.location.pathname === "/jw/web/login" && localStorage.getItem("isLoggingOut") === "true") {
    let storedLoginUrl;
    try {
      storedLoginUrl = localStorage.getItem("loginUrl");
    } catch (error) {
      console.warn("Unable to access localStorage:", error);
    }

    // Normalize URLs for comparison
    const currentFullPath = (window.location.pathname + (window.location.search || "")).replace(/\/$/, "");
    const normalizedStoredUrl = storedLoginUrl ? storedLoginUrl.replace(/\/$/, "") : null;



    // Clear logout flag and login URL
    try {
      localStorage.removeItem("isLoggingOut");
      localStorage.removeItem("loginUrl");
    } catch (error) {
      console.warn("Unable to clear localStorage:", error);
    }

    // Redirect if stored URL exists and differs from current URL
    if (normalizedStoredUrl && normalizedStoredUrl !== currentFullPath) {
      setTimeout(function () {
        window.location.href = normalizedStoredUrl;
      }, 0);
    } else {
      console.log("No redirect needed");
    }
  }
});
